*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#eff4e9;background:#071719;font-synthesis:none;--muted:#91a9a0;--line:rgba(222,239,222,.10);--panel:#102323;--lime:#c7e77f;--cream:#f2eedf}body{margin:0;min-width:320px;background:radial-gradient(ellipse at 38% -22%,#194143 0,#0a2022 49%,#061416 100%);min-height:100vh}.game-shell{max-width:1600px;margin:auto;padding:0 40px;min-height:100vh;display:flex;flex-direction:column}.topbar{height:78px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#f7f4e8}.brand-mark{width:36px;height:36px;border-radius:11px;display:grid;place-items:center;background:var(--lime);color:#163228;font-size:22px;font-weight:bold}.brand-copy{display:grid;line-height:1}.brand-copy strong{font:700 14px Outfit;letter-spacing:1.55px}.brand-copy small{font-size:9px;letter-spacing:3.5px;color:#a6bcaa;margin-top:5px}.island-label{display:flex;gap:12px;align-items:center;font-size:10px;letter-spacing:1.15px;color:#aec0b6;font-weight:600}.island-label i{font-style:normal;color:#587168}.live-dot,.pulse{display:inline-block;width:7px;height:7px;border-radius:50%;background:#c9e682;box-shadow:0 0 11px #bde980}.top-actions{display:flex;gap:10px;align-items:center}.day-pill{height:34px;padding:0 13px;border:1px solid var(--line);background:#102626;border-radius:20px;display:flex;align-items:center;gap:7px;color:#dce7d7;font-size:10px;font-weight:700;letter-spacing:.6px}.day-pill span:first-child{color:var(--lime);font-size:15px}.icon-btn{width:34px;height:34px;border-radius:50%;border:1px solid var(--line);background:#102626;color:#dbe8da;font-size:15px;cursor:pointer}.icon-btn:hover,.map-controls button:hover{border-color:var(--lime);color:var(--lime)}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 342px;gap:27px;padding:28px 0 22px;flex:1}.world-panel{display:flex;flex-direction:column;min-width:0}.world-topline{display:flex;justify-content:space-between;align-items:flex-end;padding:0 4px 17px}.eyebrow{font-size:9px;font-weight:700;letter-spacing:1.65px;color:#92aa9d}.world-topline h1{font:600 clamp(24px,2.7vw,35px)/1.07 Outfit;margin:7px 0 0;letter-spacing:-.8px;color:#f4f3e7}.world-topline h1 em{font-weight:500;color:var(--lime)}.world-coords{text-align:right;font-size:9px;letter-spacing:1px;font-weight:700;color:#d4dfcb;padding-bottom:4px}.world-coords .pin{display:block;color:var(--lime);font-size:19px;margin-bottom:3px}.world-coords small{display:block;color:#779187;font-size:8px;font-weight:500;margin-top:6px;letter-spacing:.7px}.world-coords small b{color:#bdcec1;font-weight:600}.world-frame{height:clamp(410px,56vh,620px);position:relative;overflow:hidden;border:1px solid rgba(195,229,182,.18);border-radius:15px;background:#357e79;box-shadow:0 20px 60px #031112a6;isolation:isolate}canvas{width:100%;height:100%;display:block}.map-controls{position:absolute;top:15px;right:15px;display:flex;align-items:center;gap:8px;border:1px solid #e3f2d13d;background:#09201fbb;backdrop-filter:blur(8px);padding:5px;border-radius:8px;color:#c6d6c6;font-size:8px;letter-spacing:1.5px}.map-controls button{border:1px solid #d5e6d11c;border-radius:5px;width:25px;height:25px;color:#f2f4e7;background:#173531;cursor:pointer;font-size:16px;line-height:1}.world-legend{position:absolute;left:15px;top:15px;display:flex;gap:13px;border:1px solid #e3f2d13d;background:#09201fbb;padding:9px 11px;border-radius:7px;color:#e0e9d8;font-size:8px;letter-spacing:1px}.world-legend i{display:inline-block;width:7px;height:7px;border-radius:50%;margin-right:5px}.legend-player{background:#ffdf8a;box-shadow:0 0 8px #fff3ad}.legend-resource{background:#c6e583}.world-footer{display:flex;justify-content:space-between;padding:12px 3px;color:#789288;font-size:8px;letter-spacing:1.15px;font-weight:600}.world-footer span:first-child{color:#a7bcaa}.pulse{width:6px;height:6px;margin-right:6px}.world-footer b{color:#4f7167;margin:0 6px}.world-footer span:last-child{color:#b4cf8d}.hud{display:flex;flex-direction:column;gap:15px}.survivor-card,.quest-card{border:1px solid var(--line);background:linear-gradient(135deg,#142c2b,#102322);border-radius:12px;padding:16px}.survivor-heading{display:flex;align-items:center;gap:11px;padding-bottom:14px;border-bottom:1px solid var(--line)}.avatar{width:37px;height:37px;border-radius:10px;background:#d2e994;color:#243b2b;display:grid;place-items:center;font-size:19px}.survivor-heading>div:nth-child(2){display:grid;gap:3px}.survivor-heading .eyebrow{font-size:8px}.survivor-heading strong{font:600 16px Outfit}.level{margin-left:auto;border:1px solid #cfeb9240;background:#cbe68012;color:#d6e7ad;padding:5px 8px;border-radius:6px;font-size:8px;letter-spacing:.8px}.level b{font-size:10px}.vitals{display:grid;gap:11px;padding-top:13px}.vital-label{display:flex;justify-content:space-between;color:#91aaa0;font-size:8px;letter-spacing:.7px;font-weight:700;margin-bottom:6px}.vital-label b{color:#e6eadb;font-size:9px}.bar{height:5px;background:#243a36;border-radius:8px;overflow:hidden}.bar i{display:block;height:100%;border-radius:8px;transition:width .25s}.health-fill{background:linear-gradient(90deg,#f17f6f,#ffa585)}.hunger-fill{background:linear-gradient(90deg,#e1b665,#f1d27d)}.thirst-fill{background:linear-gradient(90deg,#5eb8b6,#8be0cf)}.section-heading{display:flex;align-items:end;justify-content:space-between;margin-bottom:10px}.section-heading h2{font:600 19px Outfit;margin:3px 0 0;color:#f2f1e5}.section-heading .eyebrow{font-size:8px}.capacity{font-size:9px;color:#91a99f;padding-bottom:3px}.inventory-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:7px}.item-slot{height:67px;border:1px solid #dcebd117;border-radius:8px;background:#122725;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:4px;position:relative}.item-slot .item-icon{font-size:18px;filter:drop-shadow(0 2px 3px #0006)}.item-slot .item-name{font-size:7px;color:#9eb2a2;letter-spacing:.55px;text-transform:uppercase}.item-slot .item-count{position:absolute;right:6px;top:5px;font-size:9px;color:#e5efdb;font-weight:700}.item-slot.empty{border-style:dashed;background:#0d2020}.item-slot.empty:after{content:'·';color:#567067;font-size:18px}.quick-actions{margin-top:0}.compact{margin-bottom:9px}.action-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.action-card{height:67px;position:relative;padding:9px 9px 8px 40px;text-align:left;background:#122725;border:1px solid var(--line);border-radius:8px;color:#e9eddf;cursor:pointer;transition:transform .15s,border-color .15s,background .15s}.action-card:hover{transform:translateY(-2px);background:#183431;border-color:#cbe68188}.action-icon{position:absolute;left:10px;top:13px;width:23px;height:23px;border-radius:7px;display:grid;place-items:center;font-size:14px}.craft-icon{background:#d6b46d22;color:#e3c179}.build-icon{background:#9acb8020;color:#bbdb8b}.mission-icon{background:#bca2e922;color:#ceb6f1}.shop-icon{background:#67c8c221;color:#82d8c6}.action-card b{display:block;font:600 12px Outfit}.action-card small{display:block;color:#8da49a;font-size:8px;margin-top:4px}.action-arrow{position:absolute;right:8px;top:7px;color:#759086;font-size:11px}.quest-card{margin-top:auto;padding:13px 15px}.quest-top{display:flex;align-items:center;gap:7px;margin-bottom:10px}.quest-icon{width:21px;height:21px;border-radius:6px;background:#d6e9821d;color:#cee97d;display:grid;place-items:center;font-size:12px}.quest-top .eyebrow{font-size:8px}.quest-reward{margin-left:auto;color:#d4e999;font-size:9px;font-weight:700}.quest-card>strong{font:600 13px Outfit}.quest-card p{color:#8fa69a;font-size:9px;line-height:1.5;margin:5px 0 10px}.quest-progress{display:flex;align-items:center;gap:9px}.quest-progress .bar{flex:1;height:4px}.quest-progress .bar i{background:var(--lime);width:0}.quest-progress span{font-size:8px;color:#b9c9b8;min-width:24px;text-align:right}.bottom-bar{height:63px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex-shrink:0}.tip{display:flex;align-items:center;gap:11px;color:#d2e9a1}.tip>span:first-child{font-size:17px}.tip span:last-child{display:grid;gap:3px}.tip b{font-size:8px;letter-spacing:1.3px}.tip i{font-style:normal;font-size:9px;color:#92a89d}.footer-stats{display:flex;align-items:center;gap:20px;font-size:8px;color:#88a096;letter-spacing:.7px}.footer-stats b{color:#d8e6d1}.footer-stats button{border:0;background:none;color:#94aaa0;font:600 8px 'DM Sans';letter-spacing:.8px;cursor:pointer}.footer-stats button:hover{color:var(--lime)}.modal-backdrop{display:none;position:fixed;inset:0;background:#041313bb;backdrop-filter:blur(7px);z-index:10;align-items:center;justify-content:center;padding:20px}.modal-backdrop.open{display:flex}.modal{width:min(470px,100%);max-height:85vh;overflow:auto;background:#102625;border:1px solid #d3e6cf30;border-radius:15px;padding:25px;box-shadow:0 30px 90px #0009;position:relative}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#a6b8ad;font-size:24px;cursor:pointer}.modal h2{font:600 25px Outfit;margin:5px 0 5px}.modal .eyebrow{color:var(--lime)}.modal-intro{font-size:11px;color:#91a99e;line-height:1.55;margin:5px 25px 19px 0}.recipe-list{display:grid;gap:9px}.recipe{border:1px solid var(--line);background:#142c2a;border-radius:9px;padding:12px;display:flex;align-items:center;gap:11px}.recipe-icon{font-size:23px;width:38px;height:38px;border-radius:9px;background:#d5e89014;display:grid;place-items:center}.recipe-info{flex:1}.recipe-info b{font:600 12px Outfit}.recipe-info small{display:block;font-size:9px;color:#8ea69b;margin-top:4px}.primary-btn,.secondary-btn{border:0;border-radius:6px;padding:9px 12px;font:700 9px 'DM Sans';letter-spacing:.3px;cursor:pointer}.primary-btn{background:var(--lime);color:#203525}.primary-btn:hover{background:#def49c}.primary-btn:disabled{opacity:.42;cursor:not-allowed}.secondary-btn{background:#243d36;color:#c8d6c9}.message-row{font-size:10px;color:#d7e5cd;margin-top:13px;min-height:14px}.mission-list{display:grid;gap:10px}.mission{border:1px solid var(--line);border-radius:9px;padding:12px;display:flex;gap:11px;align-items:center}.mission>span{font-size:21px;color:#c8e683}.mission div{flex:1}.mission b{font:600 12px Outfit}.mission small{display:block;color:#8da398;margin-top:4px;font-size:9px}.mission .claimed{color:#b5c3b4;font-size:9px}.help-pop{display:none;position:fixed;z-index:15;right:35px;top:70px;width:260px;padding:15px;border:1px solid var(--line);border-radius:10px;background:#142b29;box-shadow:0 10px 30px #0006;font-size:11px}.help-pop.open{display:block}.help-pop b{font:600 13px Outfit}.help-pop p{color:#a5b8ab;line-height:1.6}.help-pop kbd{background:#29413b;border:1px solid #49635a;padding:2px 5px;border-radius:3px;margin-right:3px}.world-toast{position:absolute;top:64px;left:50%;transform:translate(-50%,-8px);background:#0d2622e8;border:1px solid #d4ef8b67;color:#e1f3b2;border-radius:7px;padding:8px 13px;font-size:10px;font-weight:600;opacity:0;transition:.2s;pointer-events:none;white-space:nowrap;z-index:3}.world-toast.show{opacity:1;transform:translate(-50%,0)}.mobile-pad{display:none;position:absolute;bottom:15px;left:15px}.mobile-pad button{border:1px solid #d6e4cc52;background:#0a201dc9;color:#eff3e5;width:39px;height:37px;border-radius:8px;margin:2px;font-size:15px}.mobile-pad>div{display:flex}
@media(min-height:900px){.game-layout{align-items:stretch}.world-frame{height:clamp(510px,63vh,690px)}.hud{gap:19px}.survivor-card{padding:18px}.inventory-grid{gap:9px}.item-slot{height:75px}.action-card{height:72px}}
@media(max-width:1020px){.game-shell{padding:0 24px}.game-layout{grid-template-columns:minmax(0,1fr) 300px;gap:17px}.world-frame{height:55vh;min-height:390px}.world-footer span:nth-child(2){display:none}.hud{gap:12px}}
@media(max-width:760px){.game-shell{padding:0 14px}.topbar{height:62px}.island-label{display:none}.game-layout{grid-template-columns:1fr;padding-top:18px;gap:16px}.world-topline h1{font-size:28px}.world-frame{height:54vh;min-height:350px}.hud{display:grid;grid-template-columns:1fr 1fr;gap:12px}.survivor-card{grid-column:1/-1}.quick-actions{grid-column:1/-1}.quest-card{grid-column:1/-1;margin-top:0}.inventory-grid{grid-template-columns:repeat(4,1fr)}.item-slot{height:61px}.bottom-bar{height:auto;min-height:65px;gap:10px}.tip i{max-width:240px;line-height:1.4}.footer-stats{gap:9px}.footer-stats>span:first-child{display:none}.world-footer{font-size:7px}.mobile-pad{display:block}}
@media(max-width:440px){.game-shell{padding:0 10px}.top-actions{gap:6px}.day-pill{padding:0 8px;font-size:8px}.world-topline h1{font-size:24px}.world-coords{font-size:8px}.world-frame{height:49vh;min-height:325px}.hud{grid-template-columns:1fr}.survivor-card,.quick-actions,.quest-card{grid-column:1}.inventory-section{grid-column:1}.tip i{max-width:150px}.footer-stats{font-size:7px}.footer-stats button{font-size:7px}.world-footer span:last-child{display:none}}

(() => {
  const canvas = document.getElementById('world'), ctx = canvas.getContext('2d');
  const $ = (s) => document.querySelector(s);
  const itemDefs = {wood:{name:'Wood',icon:'🪵'},stone:{name:'Stone',icon:'🪨'},berries:{name:'Berries',icon:'🫐'},coconut:{name:'Coconut',icon:'🥥'},water:{name:'Fresh water',icon:'💧'},fiber:{name:'Fiber',icon:'🌿'},shells:{name:'Shells',icon:'🐚'},axe:{name:'Stone axe',icon:'🪓'},spear:{name:'Wood spear',icon:'🔱'},campfire:{name:'Campfire',icon:'🔥'},shelter:{name:'Lean-to',icon:'⛺'}};
  const initial = {items:{wood:0,stone:0,berries:0,coconut:0,water:0,fiber:0},health:100,hunger:82,thirst:76,shells:0,level:1,x:.51,y:.57,day:1,minute:480,xp:0,crafted:{},built:{},questDone:false,gotReward:false};
  let state; try {state={...initial,...JSON.parse(localStorage.getItem('survival-island-save')||'{}')};state.items={...initial.items,...(state.items||{})};state.crafted||={};state.built||={};} catch {state={...initial,items:{...initial.items},crafted:{},built:{}};}
  let zoom=1, toastTimer, lastTick=Date.now(), moving=new Set(), overlay=null, lastSave=0;
  const resources=[
    {type:'tree',x:.48,y:.51,amount:8},{type:'tree',x:.60,y:.63,amount:8},{type:'tree',x:.37,y:.46,amount:8},{type:'tree',x:.68,y:.49,amount:8},{type:'tree',x:.44,y:.68,amount:8},{type:'tree',x:.72,y:.68,amount:8},{type:'rock',x:.56,y:.44,amount:6},{type:'rock',x:.33,y:.57,amount:6},{type:'rock',x:.65,y:.39,amount:6},{type:'bush',x:.54,y:.65,amount:5},{type:'bush',x:.41,y:.55,amount:5},{type:'palm',x:.55,y:.76,amount:3},{type:'palm',x:.27,y:.47,amount:3},{type:'palm',x:.76,y:.56,amount:3},{type:'spring',x:.61,y:.54,amount:8}
  ];
  const recipes=[{id:'axe',icon:'🪓',name:'Stone axe',desc:'Gather wood 2× faster.',cost:{wood:5,stone:3},action:'craft'},{id:'spear',icon:'🔱',name:'Wood spear',desc:'A sturdy tool for island life.',cost:{wood:4,fiber:2},action:'craft'},{id:'campfire',icon:'🔥',name:'Campfire',desc:'A warm place to cook and rest.',cost:{wood:6,stone:3},action:'craft'}];
  const buildings=[{id:'shelter',icon:'⛺',name:'Palm lean-to',desc:'A safe place to rest. Restores health.',cost:{wood:12,fiber:5}},{id:'camp',icon:'🏕️',name:'Beach camp',desc:'A cozy home base on the shore.',cost:{wood:8,stone:4}}];
  const missions=[{id:'wood',icon:'🪵',name:'Gather your bearings',desc:'Collect 5 wood to get your first campfire going.',goal:5,progress:()=>state.items.wood+(state.crafted.campfire?6:0),reward:25},{id:'water',icon:'💧',name:'Find fresh water',desc:'Collect 3 fresh water from the island spring.',goal:3,progress:()=>state.items.water,reward:20},{id:'shelter',icon:'⛺',name:'A place to call home',desc:'Build your first palm lean-to.',goal:1,progress:()=>state.built.shelter||0,reward:35}];
  function save(){try{localStorage.setItem('survival-island-save',JSON.stringify(state));$('#save-state').textContent='SAVED LOCALLY';}catch{$('#save-state').textContent='SESSION ONLY';}}
  function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  function addItem(key,n){state.items[key]=(state.items[key]||0)+n;state.xp+=n;while(state.xp>=20){state.xp-=20;state.level++;toast(`Level up! You're now level ${state.level}.`)} }
  function canPay(cost){return Object.entries(cost).every(([k,n])=>(state.items[k]||0)>=n)}
  function pay(cost){Object.entries(cost).forEach(([k,n])=>state.items[k]-=n)}
  function actionGather(obj){if(!obj||obj.amount<=0){toast('There is nothing left to gather here.');return}const dist=Math.hypot(obj.x-state.x,obj.y-state.y);if(dist>.18){toast('Move a little closer to gather this.');return}let key,n;
    if(obj.type==='tree'){key='wood';n=state.crafted.axe?2:1}
    else if(obj.type==='rock'){key='stone';n=1}
    else if(obj.type==='bush'){key='berries';n=1;if(Math.random()>.4)addItem('fiber',1)}
    else if(obj.type==='palm'){key='coconut';n=1}
    else {key='water';n=1}
    obj.amount--;addItem(key,n);if(key==='berries')state.hunger=Math.min(100,state.hunger+7);if(key==='coconut'){state.thirst=Math.min(100,state.thirst+9);state.hunger=Math.min(100,state.hunger+3)}if(key==='water')state.thirst=Math.min(100,state.thirst+4);
    toast(`+${n} ${itemDefs[key].name}${obj.amount===0?' · resource depleted':''}`);renderUI();save();
  }
  function draw(){const rect=canvas.getBoundingClientRect();const dpr=Math.min(devicePixelRatio||1,2);if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);const w=rect.width,h=rect.height,s=Math.min(w/900,h/630)*zoom,ox=(w-900*s)/2,oy=(h-630*s)/2;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(ox,oy);ctx.scale(s,s);drawWorld();ctx.restore();requestAnimationFrame(draw)}
  function drawWorld(){const c=ctx;let w=900,h=630;let grad=c.createLinearGradient(0,0,900,630);grad.addColorStop(0,'#2d7f83');grad.addColorStop(.55,'#1c6970');grad.addColorStop(1,'#174f5c');c.fillStyle=grad;c.fillRect(0,0,w,h);
    // layered water shimmer
    for(let i=0;i<110;i++){let x=(i*173+31)%930-15,y=(i*97+53)%650;c.beginPath();c.ellipse(x,y,7+(i%5)*2,1.3,Math.sin(i)*.08,0,Math.PI*2);c.fillStyle=i%3===0?'#b9e8d521':'#b9e8d510';c.fill()}
    c.save();c.translate(453,315);c.rotate(-.08);c.scale(1.09,1);
    // island shadow & beach lip
    islandShape(c,0,10,1.025);c.fillStyle='#153f3d';c.fill();islandShape(c,0,0,1.0);c.fillStyle='#e7d49a';c.fill();
    // inner grassland
    islandShape(c,0,-1,.948);c.fillStyle='#66864d';c.fill();islandShape(c,0,-2,.89);c.fillStyle='#557d49';c.fill();
    // terrain patching
    c.fillStyle='#7d9a59';for(let i=0;i<25;i++){let x=Math.sin(i*28.5)*235,y=Math.cos(i*13.4)*158;if((x/340)**2+(y/205)**2<.75){c.beginPath();c.ellipse(x,y,22+i%7*4,7+i%4*3,i*.3,0,Math.PI*2);c.fill()}}
    // mountain ridge
    c.fillStyle='#4b6545';c.beginPath();c.moveTo(-145,-119);c.quadraticCurveTo(-75,-181,10,-129);c.quadraticCurveTo(84,-192,171,-105);c.lineTo(130,-55);c.lineTo(-113,-58);c.closePath();c.fill();c.fillStyle='#71835a';c.beginPath();c.moveTo(-63,-144);c.lineTo(-32,-173);c.lineTo(-4,-132);c.closePath();c.fill();c.beginPath();c.moveTo(68,-150);c.lineTo(94,-177);c.lineTo(118,-139);c.closePath();c.fill();
    // river
    c.beginPath();c.moveTo(55,-125);c.bezierCurveTo(39,-55,110,-16,48,32);c.bezierCurveTo(1,75,77,118,101,178);c.lineWidth=19;c.strokeStyle='#c9bc83';c.stroke();c.beginPath();c.moveTo(55,-125);c.bezierCurveTo(39,-55,110,-16,48,32);c.bezierCurveTo(1,75,77,118,101,178);c.lineWidth=11;c.strokeStyle='#53a8a0';c.stroke();
    // sand coves details
    c.fillStyle='#f0dfa8';c.beginPath();c.ellipse(-255,95,48,20,-.35,0,Math.PI*2);c.fill();c.beginPath();c.ellipse(255,-75,43,16,.4,0,Math.PI*2);c.fill();
    // foliage clusters, fixed seeded
