const saveKey='survival-island-save';
const finite=(value)=>typeof value==='number'&&Number.isFinite(value);
function loadState(){
  const fresh=()=>({...initial,items:{...initial.items},crafted:{},built:{}});
  try{
    const raw=JSON.parse(localStorage.getItem(saveKey)||'null');if(!raw||typeof raw!=='object'||Array.isArray(raw))return fresh();
    const result=fresh();
    for(const key of ['health','hunger','thirst'])if(finite(raw[key]))result[key]=Math.max(0,Math.min(100,raw[key]));
    for(const key of ['shells','level','xp','day','minute'])if(finite(raw[key]))result[key]=Math.max(key==='level'||key==='day'?1:0,Math.floor(raw[key]));
    if(finite(raw.x))result.x=Math.max(.27,Math.min(.74,raw.x));if(finite(raw.y))result.y=Math.max(.31,Math.min(.76,raw.y));
    for(const key of ['questDone','gotReward','gameOver'])if(typeof raw[key]==='boolean')result[key]=raw[key];
    if(raw.items&&typeof raw.items==='object'&&!Array.isArray(raw.items))for(const key of Object.keys(initial.items)){const n=raw.items[key];if(finite(n))result.items[key]=Math.max(0,Math.min(40,Math.floor(n)))}
    let left=40;for(const key of Object.keys(result.items)){result.items[key]=Math.min(result.items[key],left);left-=result.items[key]}
    for(const [field,allowed] of [['crafted',['axe','spear','campfire']],['built',['shelter','camp']]])if(raw[field]&&typeof raw[field]==='object'&&!Array.isArray(raw[field]))for(const id of allowed){const value=raw[field][id];if(field==='built'&&finite(value))result[field][id]=Math.max(0,Math.min(1,Math.floor(value)));else if(field==='crafted'&&typeof value==='boolean')result[field][id]=value}
    for(const m of missions)if(typeof raw[`mission_${m.id}`]==='boolean')result[`mission_${m.id}`]=raw[`mission_${m.id}`];
    if(Array.isArray(raw.resourceState))result.resourceState=raw.resourceState.slice(0,15).map(saved=>({amount:finite(saved?.amount)?Math.max(0,Math.min(8,Math.floor(saved.amount))):0,regrowAt:finite(saved?.regrowAt)?Math.max(0,saved.regrowAt):0}));
    return result;
  }catch{return fresh()}
}
let state=loadState();

